{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law deposit cap and return rules","requirement":"A landlord may not hold a deposit above one and one-half months' rent, may raise it no more than 10% a year, owes the tenant its interest, and must return it with an itemized deduction list within 30 days after the tenancy ends.","key_value":"1.5 months' rent max; 10% annual increase cap","coverage_conditions":"Residential rental tenancies in New Jersey; the deposit-holding and account provisions do not apply to seasonal use or rental of 125 consecutive days or fewer.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Statewide residential rentals; seasonal rentals of 125 days or fewer exempt from deposit-holding rules"},"exemptions":"Seasonal use or rental — not more than 125 consecutive days for residential purposes by a person with a permanent residence elsewhere — is exempt from the deposit-holding section; a landlord is not required to collect a deposit at all.","penalty":"Tenant may sue for double the amount of the deposit wrongfully withheld, plus court costs and reasonable attorney's fees.","effective_date":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic-violence lease termination","requirement":"When a tenant ends a lease early under the Safe Housing Act because of domestic violence, the landlord must make the deposit and interest available within 15 business days and notify the tenant within 3 business days where and when to collect it.","key_value":"15 business days to return deposit","coverage_conditions":"Tenants who terminate a lease under the Safe Housing Act after documenting domestic violence; does not apply to transient or seasonal rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Domestic-violence lease terminations; excludes transient or seasonal rentals"},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
